import {TIERS,createState,place,undo,load,save} from './model.js';
const $=id=>document.getElementById(id);let state=load(),selected=null;const board=$('board');
function cardContent(card){const e=document.createElement('span');e.className='emoji';e.textContent=card.emoji;const n=document.createElement('span');n.className='name';n.textContent=card.name;return [e,n];}
function current(){return state.cards.find(c=>c.id===selected)||state.cards.find(c=>!c.tier);}
function assign(tier,id=current()?.id){if(id===undefined)return;if(place(state,id,tier)){$('announcement').textContent=`${state.cards.find(c=>c.id===id).name}を${tier}に配置しました`;selected=null;render();}}
function render(){board.replaceChildren();$('board-title').textContent=state.title;let done=state.cards.filter(c=>c.tier).length;$('progress').textContent=`${done} / ${state.cards.length}`;$('progress-bar').style.width=`${done/state.cards.length*100}%`;
for(const t of TIERS){const row=document.createElement('div');row.className='tier';row.style.setProperty('--tier',t.color);const label=document.createElement('button');label.className='tier-label';label.setAttribute('aria-label',`${t.id}に配置`);label.innerHTML=`<strong>${t.id}</strong><small>${t.name}</small>`;label.onclick=()=>assign(t.id);const area=document.createElement('div');area.className='tier-content';area.onclick=()=>assign(t.id);const cards=state.cards.filter(c=>c.tier===t.id);if(!cards.length){const empty=document.createElement('span');empty.className='empty';empty.textContent='＋';area.append(empty);}for(const c of cards){const tile=document.createElement('button');tile.className='tile'+(selected===c.id?' selected':'');tile.setAttribute('aria-label',`${c.name}：${t.id}。選んで移動`);tile.append(...cardContent(c));tile.draggable=true;tile.ondragstart=e=>e.dataTransfer.setData('text/plain',c.id);tile.onclick=e=>{e.stopPropagation();selected=selected===c.id?null:c.id;render();};area.append(tile);}row.ondragover=e=>{e.preventDefault();row.classList.add('over')};row.ondragleave=()=>row.classList.remove('over');row.ondrop=e=>{e.preventDefault();row.classList.remove('over');assign(t.id,e.dataTransfer.getData('text/plain'))};row.append(label,area);board.append(row);}
const c=current();$('current').replaceChildren();if(c){const hero=document.createElement('div');hero.className='hero-card';hero.draggable=true;hero.ondragstart=e=>e.dataTransfer.setData('text/plain',c.id);hero.append(...cardContent(c));const counter=document.createElement('span');counter.className='card-counter';counter.textContent=selected?'MOVE CARD':`CARD ${String(done+1).padStart(2,'0')}`;$('current').append(hero,counter);}else{const doneEl=document.createElement('div');doneEl.className='complete';doneEl.innerHTML='<b>できあがり ✦</b>あなたの「好き」が並びました。';$('current').append(doneEl);}$('deck-label').textContent=selected?'選んだカードを移動':c?'このカードは、どのティア？':'YOUR TIER LIST IS COMPLETE';$('hint').textContent=selected?'移動先のランクをタップ':c?'下のランクをタップして配置':'表のカードをタップすると移動できます';$('choices').replaceChildren();for(const t of TIERS){const b=document.createElement('button');b.className='choice';b.style.setProperty('--tier',t.color);b.textContent=t.id;b.setAttribute('aria-label',`${t.id}に配置する`);b.disabled=!c;b.onclick=()=>assign(t.id);$('choices').append(b);}$('undo').disabled=!state.history.length;if(!save(state))document.querySelector('footer span').textContent='保存できません（この画面では操作できます）';requestAnimationFrame(fit);}
function fit(){document.querySelectorAll('.tier-content').forEach(area=>{const count=area.querySelectorAll('.tile').length;if(!count)return;const w=area.clientWidth-10,h=area.clientHeight-10;let size=1;for(let cols=1;cols<=count;cols++){const rows=Math.ceil(count/cols);const s=Math.min((w-4*(cols-1))/cols,(h-4*(rows-1))/rows,76);size=Math.max(size,s);}size=Math.floor(size);area.style.setProperty('--card-w',size+'px');area.style.setProperty('--card-h',size+'px');area.style.setProperty('--emoji-size',Math.max(7,Math.min(30,size*.47))+'px');area.style.setProperty('--name-size',Math.max(5,Math.min(9,size*.16))+'px');});}
new ResizeObserver(fit).observe(board);$('undo').onclick=()=>{undo(state);selected=null;render()};$('reset').onclick=()=>{if(!state.history.length||confirm('配置をすべてリセットしますか？')){state=createState(state.title,state.cards.map(c=>[c.emoji,c.name]));selected=null;render()}};$('settings').onclick=()=>{$('title-input').value=state.title;$('cards-input').value=state.cards.map(c=>c.name).join('\n');$('error').textContent='';$('editor').showModal()};$('apply').onclick=()=>{const names=$('cards-input').value.split('\n').map(s=>s.trim()).filter(Boolean);const title=$('title-input').value.trim();if(!title||names.length<1||names.length>30||names.some(n=>n.length>60)){$('error').textContent='タイトルと1〜30枚のカード名（各60文字以内）を入力してください。';return;}state=createState(title,names.map((name,i)=>[state.cards.find(c=>c.name===name)?.emoji||['✦','✿','◆','●','▲'][i%5],name]));selected=null;$('editor').close();render()};document.addEventListener('keydown',e=>{if($('editor').open||e.ctrlKey||e.metaKey||e.altKey)return;const key=e.key.toUpperCase();if(TIERS.some(t=>t.id===key))assign(key)});render();
